.radio-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  margin: 1.6rem 0 2rem;
}
.radio-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.6rem;
  padding: 0 1.1rem;
  box-sizing: border-box;
  font: inherit;
  text-decoration: none;
  cursor: pointer;
  border-radius: 8px;
  border: 1px solid var(--lightgray);
}
.radio-action-primary {
  color: var(--light);
  background: var(--secondary);
  border-color: var(--secondary);
}
.radio-action-primary:hover {
  background: var(--tertiary);
  border-color: var(--tertiary);
}
.radio-letter-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-width: 40rem;
  margin: 1rem 0 2.5rem;
}
.radio-letter-form[hidden] {
  display: none !important;
}
.radio-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  color: var(--darkgray);
  font-size: 0.95rem;
}
.radio-input,
.radio-textarea {
  width: 100%;
  box-sizing: border-box;
  padding: 0.7rem 0.9rem;
  font-family: inherit;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--dark);
  background: var(--light);
  border: 1px solid var(--lightgray);
  border-radius: 8px;
  transition: border-color 0.15s ease;
}
.radio-input:focus,
.radio-textarea:focus {
  outline: none;
  border-color: var(--secondary);
}
.radio-textarea {
  resize: vertical;
}
.radio-submit-row {
  display: flex;
}
.radio-submit {
  padding: 0.6rem 1.4rem;
  font-family: inherit;
  font-size: 1rem;
  color: var(--light);
  background: var(--secondary);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s ease, opacity 0.15s ease;
}
.radio-submit:hover {
  background: var(--tertiary);
}
.radio-submit:disabled {
  opacity: 0.5;
  cursor: default;
}
.radio-result {
  margin: 0;
  min-height: 1.4em;
  color: var(--gray);
  font-size: 0.95rem;
}
.radio-result.ok {
  color: var(--secondary);
}
.radio-result.err {
  color: #c0392b;
}


(function () {
  const WEB3FORMS_KEY = &quot;99adb30b-efa0-4935-8c5a-79e3faa094cd&quot;

  function initRadioLetters() {
    const toggle = document.getElementById(&quot;radio-letter-toggle&quot;)
    const form = document.getElementById(&quot;radio-letter-form&quot;)
    if (!form) return

    if (toggle &amp;&amp; !toggle.dataset.bound) {
      toggle.dataset.bound = &quot;1&quot;
      toggle.addEventListener(&quot;click&quot;, () =&gt; {
        const willOpen = form.hidden
        form.hidden = !willOpen
        toggle.setAttribute(&quot;aria-expanded&quot;, String(willOpen))
        toggle.textContent = willOpen ? &quot;收起&quot; : &quot;写来信&quot;
        if (willOpen) document.getElementById(&quot;radio-name&quot;).focus()
      })
    }

    if (form.dataset.bound) return
    form.dataset.bound = &quot;1&quot;

    const result = document.getElementById(&quot;radio-result&quot;)
    const submit = form.querySelector(&quot;.radio-submit&quot;)
    const content = document.getElementById(&quot;radio-content&quot;)
    const name = document.getElementById(&quot;radio-name&quot;)

    form.addEventListener(&quot;submit&quot;, async (event) =&gt; {
      event.preventDefault()
      if (form.botcheck &amp;&amp; form.botcheck.checked) return

      const letter = content.value.trim()
      const senderName = name.value.trim()
      if (!senderName || !letter) return

      result.className = &quot;radio-result&quot;
      result.textContent = &quot;正在寄出……&quot;
      submit.disabled = true

      try {
        const response = await fetch(&quot;api.web3forms.com/submit&quot;, {
          method: &quot;POST&quot;,
          headers: {
            Accept: &quot;application/json&quot;,
            &quot;Content-Type&quot;: &quot;application/json&quot;,
          },
          body: JSON.stringify({
            access_key: WEB3FORMS_KEY,
            subject: &quot;小浩日记 · 电台来信&quot;,
            from_name: &quot;电台来信箱&quot;,
            称呼: senderName,
            使用方式: &quot;直接转发到站长邮箱，不公开显示&quot;,
            来信: letter,
          }),
        })
        const data = await response.json()
        if (!response.ok || data.success === false) {
          throw new Error(&quot;submit failed&quot;)
        }

        form.reset()
        result.className = &quot;radio-result ok&quot;
        result.textContent = &quot;收到啦，来信已经寄到我这里。&quot;
      } catch (_) {
        result.className = &quot;radio-result err&quot;
        result.textContent = &quot;寄出失败了，稍后再试试？&quot;
      } finally {
        submit.disabled = false
      }
    })
  }

  initRadioLetters()
  document.addEventListener(&quot;nav&quot;, initRadioLetters)
})()
